#!/usr/bin/env bash
set -euo pipefail

# build-package.sh — produce a redistributable tarball of Hive.
#
# Output: dist/hive-<version>.tar.gz + dist/hive-<version>.sha256
#
# The tarball extracts to a single top-level directory (hive-<version>/) so
# users get a clean working tree. Excludes:
#   - venv/                      (recreated by install.sh on the target machine)
#   - dist/                      (don't ship build artifacts)
#   - __pycache__/, *.pyc        (Python build leftovers)
#   - .git, .gitignore           (no VCS state)
#   - share/docs/MCP-TOOLS.md    (regenerated by install.sh from current tools)
#   - any .company/, .worktrees/ test artifacts
#
# Usage: build-package.sh [--version X.Y.Z] [--out-dir DIR]
#
# Run from anywhere: the script resolves paths relative to itself.

SOURCE_DIR="$(cd "$(dirname "$0")/.." && pwd)"
OUT_DIR="$SOURCE_DIR/dist"
VERSION=""

while [ $# -gt 0 ]; do
  case "$1" in
    --version) VERSION="$2"; shift 2 ;;
    --out-dir) OUT_DIR="$2"; shift 2 ;;
    -h|--help)
      cat <<EOF
Usage: build-package.sh [--version X.Y.Z] [--out-dir DIR]
  --version  Override version (default: read from VERSION file)
  --out-dir  Where to put the tarball (default: $SOURCE_DIR/dist)
EOF
      exit 0 ;;
    *) echo "Unknown option: $1" >&2; exit 1 ;;
  esac
done

if [ -z "$VERSION" ]; then
  if [ -f "$SOURCE_DIR/VERSION" ]; then
    VERSION="$(tr -d '[:space:]' < "$SOURCE_DIR/VERSION")"
  else
    VERSION="0.0.0-dev"
  fi
fi

PKG_NAME="hive-$VERSION"
TARBALL="$OUT_DIR/${PKG_NAME}.tar.gz"
CHECKSUM="$OUT_DIR/${PKG_NAME}.sha256"

mkdir -p "$OUT_DIR"

# Build a clean copy in a temp dir so we can prune without disturbing the source
STAGE="$(mktemp -d -t hive-build-XXXXXX)"
trap 'rm -rf "$STAGE"' EXIT

echo "Staging Hive $VERSION → $STAGE/$PKG_NAME"
mkdir -p "$STAGE/$PKG_NAME"

# Copy everything we want to ship
for d in bin lib etc share packaging VERSION; do
  if [ -e "$SOURCE_DIR/$d" ]; then
    cp -r "$SOURCE_DIR/$d" "$STAGE/$PKG_NAME/"
  fi
done

# Top-level README + LICENSE + INSTALL convenience files
cp "$SOURCE_DIR/share/docs/README.md" "$STAGE/$PKG_NAME/README.md"
cat > "$STAGE/$PKG_NAME/INSTALL" <<EOF
Hive $VERSION — installation

  1. Extract this archive (you've already done this)
  2. Run: bash packaging/install.sh --copy-to ~/.local/share/hive
  3. Verify: hive doctor

That copies the tree to ~/.local/share/hive, creates a Python venv there with
required packages, and symlinks ~/.local/bin/hive → bin/hive.

For more docs, see share/docs/README.md, ARCHITECTURE.md, CLI.md, MCP-TOOLS.md.
EOF
cat > "$STAGE/$PKG_NAME/LICENSE" <<EOF
Hive — orchestration framework for AI agents
Copyright (c) 2026

Permission is hereby granted, free of charge, to any person obtaining a copy
of this software and associated documentation files (the "Software"), to deal
in the Software without restriction.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND.
EOF

# Prune things that shouldn't ship
echo "Pruning build artifacts and caches..."
find "$STAGE/$PKG_NAME" -type d -name '__pycache__' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name '.git' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name 'venv' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name 'dist' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name '.company' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name '.worktrees' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name 'node_modules' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -name '*.pyc' -delete
find "$STAGE/$PKG_NAME" -name '*.pyo' -delete
find "$STAGE/$PKG_NAME" -name '.DS_Store' -delete
find "$STAGE/$PKG_NAME" -name '*.swp' -delete

# Make sure scripts are executable
chmod +x "$STAGE/$PKG_NAME/bin/hive"
chmod +x "$STAGE/$PKG_NAME/lib/core/"*.sh
chmod +x "$STAGE/$PKG_NAME/lib/tools/"*.sh
chmod +x "$STAGE/$PKG_NAME/packaging/"*.sh

# Build deterministic tarball (sorted file list, fixed mtimes from VERSION file)
echo "Creating tarball..."
tar --create --gzip \
  --owner=0 --group=0 \
  --sort=name \
  --mtime="@$(stat -c %Y "$SOURCE_DIR/VERSION")" \
  -f "$TARBALL" \
  -C "$STAGE" "$PKG_NAME"

# Checksum
( cd "$OUT_DIR" && sha256sum "${PKG_NAME}.tar.gz" > "${PKG_NAME}.sha256" )

echo ""
echo "Built:"
echo "  $TARBALL ($(du -h "$TARBALL" | cut -f1))"
echo "  $CHECKSUM"
echo ""
echo "Install on a target machine:"
echo "  curl -L <url-to-tarball> | tar xz"
echo "  cd $PKG_NAME"
echo "  bash packaging/install.sh --copy-to ~/.local/share/hive"
echo ""
echo "Or via the one-liner installer (set HIVE_PKG_URL):"
echo "  curl -fsSL <url-to-install-online.sh> | sh"
